"""Apply and run RABIT-2 Stage 3A without downloading or extracting a ZIP.

Run this file from the kvquant_pkg directory using the Python environment that
has Modal installed. It backs up affected files, writes the Stage 3A sources,
creates a frozen vLLM snapshot, and launches the H100 correctness check.
"""
from __future__ import annotations

import base64
import os
import shutil
import subprocess
import sys
import tempfile
import time
import zipfile
import zlib
from pathlib import Path

PROJECT_ROOT = Path.cwd().resolve()
VLLM_ROOT = PROJECT_ROOT / "vllm-kvquant"
BACKUP_ROOT = PROJECT_ROOT / "rabit2_stage3a_backup"
SNAPSHOT_PATH = Path(tempfile.gettempdir()) / "rabit2_stage3a_vllm_snapshot.zip"
RUNNER_PATH = Path(tempfile.gettempdir()) / "modal_rabit2_stage3a_frozen_test.py"
LOG_PATH = PROJECT_ROOT / "rabit2_stage3a_physical.log"

PAYLOADS = {
    'vllm-kvquant/vllm/v1/attention/ops/rabit_kv2.py': '',
    'vllm-kvquant/vllm/v1/kv_cache_interface.py': '',
    'vllm-kvquant/tests/quantization/test_rabit_kv2_layout.py': '',
    'vllm-kvquant/tests/quantization/test_rabit_kv2_physical.py': '',
}

RUNNER_SOURCE = '"""Frozen RABIT-KV2 Stage 3A Modal runner."""\n\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nimport modal\n\nBASE_COMMIT = "f329ce405b12623fb8b1cf1830f12e5a712523be"\nAPP_NAME = "rabit2-stage3a-physical-codec-test"\nSNAPSHOT_PATH = Path(os.environ["RABIT_VLLM_SNAPSHOT"]).resolve()\nSNAPSHOT = SNAPSHOT_PATH\nif not SNAPSHOT.is_file():\n    raise FileNotFoundError(f"Missing frozen snapshot: {SNAPSHOT}")\n\napp = modal.App(APP_NAME)\n\nimage = (\n    modal.Image.from_registry(\n        "nvidia/cuda:13.0.2-devel-ubuntu22.04", add_python="3.11"\n    )\n    .apt_install("git", "curl", "libnuma1", "libnuma-dev")\n    .pip_install(\n        "pip>=25", "cmake>=3.26.1", "ninja", "packaging>=24.2",\n        "setuptools>=77.0.3,<81.0.0", "setuptools-scm>=8.0",\n        "setuptools-rust>=1.9.0", "wheel", "jinja2", "pytest>=7", "tblib>=3.0",\n    )\n    .run_commands(\n        "python -m pip install torch==2.11.0 torchvision==0.26.0 "\n        "torchaudio==2.11.0 --index-url https://download.pytorch.org/whl/cu130"\n    )\n    .add_local_file(str(SNAPSHOT), "/tmp/rabit2_stage3a_vllm_snapshot.zip", copy=True)\n    .run_commands(\n        "rm -rf /root/vllm-kvquant && mkdir -p /root/vllm-kvquant && "\n        "python -m zipfile -e /tmp/rabit2_stage3a_vllm_snapshot.zip /root/vllm-kvquant"\n    )\n    .env(\n        {\n            "CUDA_HOME": "/usr/local/cuda",\n            "VLLM_TARGET_DEVICE": "cuda",\n            "VLLM_USE_PRECOMPILED": "1",\n            "VLLM_PRECOMPILED_WHEEL_COMMIT": BASE_COMMIT,\n            "VLLM_PRECOMPILED_WHEEL_VARIANT": "cu130",\n            "VLLM_MAIN_CUDA_VERSION": "13.0",\n            "VLLM_SKIP_PRECOMPILED_VERSION_SUFFIX": "1",\n            "SETUPTOOLS_SCM_PRETEND_VERSION": "0.10.0+kvquant",\n            "SETUPTOOLS_SCM_PRETEND_VERSION_FOR_VLLM": "0.10.0+kvquant",\n            "PIP_DISABLE_PIP_VERSION_CHECK": "1",\n        }\n    )\n    .run_commands(\n        "cd /root/vllm-kvquant && python use_existing_torch.py --prefix",\n        "cd /root/vllm-kvquant && rm -rf build dist *.egg-info "\n        "/tmp/vllm_precompiled_install.log && "\n        "(python -m pip install -e . --no-build-isolation "\n        "> /tmp/vllm_precompiled_install.log 2>&1 || "\n        "(echo \'===== INSTALL FAILED: FINAL 250 LINES =====\'; "\n        "tail -n 250 /tmp/vllm_precompiled_install.log; exit 1)) && "\n        "echo \'===== PRECOMPILED INSTALL COMPLETED =====\' && "\n        "tail -n 25 /tmp/vllm_precompiled_install.log",\n    )\n)\n\n\n@app.function(image=image, gpu="H100", timeout=1800)\ndef verify_stage3a() -> None:\n    import subprocess\n    import sys\n\n    import torch\n    import vllm\n\n    from vllm.v1.attention.ops.rabit_kv2 import Rabit2OnlineStateRef\n    from vllm.v1.kv_cache_interface import (\n        rabit2_effective_compression_with_staging,\n        rabit2_exact_online_staging_bytes_per_sequence,\n        rabit2_page_layout,\n    )\n\n    print("=" * 92)\n    print("RABIT-2 Stage 3A physical page codec + exact online state check")\n    print("=" * 92)\n    print(f"Base wheel commit: {BASE_COMMIT}")\n    print(f"Python:            {sys.version.split()[0]}")\n    print(f"PyTorch:           {torch.__version__}")\n    print(f"CUDA runtime:      {torch.version.cuda}")\n    print(f"GPU:               {torch.cuda.get_device_name(0)}")\n    print(f"vLLM version:      {getattr(vllm, \'__version__\', \'unknown\')}")\n\n    layout = rabit2_page_layout(\n        block_size=32, num_kv_heads=8, head_size_k=128, head_size_v=128\n    )\n    staging = rabit2_exact_online_staging_bytes_per_sequence(\n        num_kv_heads=8, head_size_k=128, head_size_v=128\n    )\n    print("\\nLlama-3.1-8B corrected physical accounting:")\n    print(f"  page bytes:                    {layout.page_bytes:8d}")\n    print(f"  exact online staging:          {staging:8d}")\n    for context in (1024, 4096, 16384):\n        comp = rabit2_effective_compression_with_staging(\n            context_tokens=context,\n            block_size=32,\n            num_kv_heads=8,\n            head_size_k=128,\n            head_size_v=128,\n        )\n        print(f"  effective compression @{context // 1024:>2}K: {comp:8.3f}x")\n\n    # Direct CUDA construction proves the new module imports and can maintain\n    # its buffers on the target device; detailed equality is covered by pytest.\n    state = Rabit2OnlineStateRef(\n        num_kv_heads=8, head_size_k=128, head_size_v=128\n    )\n    k = torch.randn(36, 8, 128, dtype=torch.bfloat16, device="cuda")\n    v = torch.randn_like(k)\n    state.append(k, v)\n    decoded_k, decoded_v = state.materialize(dtype=torch.float32)\n    print("\\nCUDA physical-state smoke:")\n    print(f"  closed pages:       {len(state.pages)}")\n    print(f"  decoded K shape:    {tuple(decoded_k.shape)}")\n    print(f"  decoded V shape:    {tuple(decoded_v.shape)}")\n    print(f"  current bytes:      {state.storage_breakdown()[\'total\']}")\n\n    result = subprocess.run(\n        [\n            sys.executable,\n            "-m",\n            "pytest",\n            "/root/vllm-kvquant/tests/quantization/test_kvquant_k3.py",\n            "/root/vllm-kvquant/tests/quantization/test_rabit_kv2_layout.py",\n            "/root/vllm-kvquant/tests/quantization/test_rabit_kv2_physical.py",\n            "--confcutdir=/root/vllm-kvquant/tests/quantization",\n            "-q",\n            "--tb=short",\n        ],\n        text=True,\n        capture_output=True,\n        check=False,\n    )\n    print("\\n" + result.stdout)\n    if result.stderr:\n        print(result.stderr)\n    print(f"pytest exit code: {result.returncode}")\n    if result.returncode:\n        raise RuntimeError("RABIT-2 Stage 3A physical codec tests failed")\n    print("RABIT-2 STAGE 3A PHYSICAL CODEC CHECK PASSED")\n    print("Stage 3B will replace the Python page codec/read path with Triton kernels.")\n\n\n@app.local_entrypoint()\ndef main() -> None:\n    verify_stage3a.remote()\n'

IGNORED_DIR_NAMES = {
    ".git", ".github", ".buildkite", ".venv", "__pycache__", "build",
    "dist", "docs", "examples", "benchmarks", ".deps", ".pytest_cache",
    ".mypy_cache", ".ruff_cache",
}
IGNORED_SUFFIXES = {".pyc", ".pyo", ".so", ".dll", ".dylib"}


def _decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value.encode("ascii")))


def _install_files() -> None:
    if not VLLM_ROOT.is_dir():
        raise FileNotFoundError(
            f"Expected vLLM fork at {VLLM_ROOT}. Run this file from kvquant_pkg."
        )
    BACKUP_ROOT.mkdir(parents=True, exist_ok=True)
    for rel, encoded in PAYLOADS.items():
        target = PROJECT_ROOT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        backup = BACKUP_ROOT / rel
        if target.exists() and not backup.exists():
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)
        target.write_bytes(_decode(encoded))
        print(f"Installed: {target}")


def _include(path: Path) -> bool:
    rel = path.relative_to(VLLM_ROOT)
    return (
        path.is_file()
        and not any(part in IGNORED_DIR_NAMES for part in rel.parts)
        and path.suffix.lower() not in IGNORED_SUFFIXES
        and not path.name.endswith(".egg-info")
    )


def _make_snapshot() -> None:
    tmp = SNAPSHOT_PATH.with_suffix(".zip.tmp")
    for path in (tmp, SNAPSHOT_PATH):
        try:
            path.unlink()
        except FileNotFoundError:
            pass
    count = 0
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        for path in sorted(VLLM_ROOT.rglob("*")):
            if _include(path):
                zf.write(path, path.relative_to(VLLM_ROOT).as_posix())
                count += 1
    os.replace(tmp, SNAPSHOT_PATH)
    print(
        f"Created frozen vLLM snapshot: {SNAPSHOT_PATH} "
        f"({count} files, {SNAPSHOT_PATH.stat().st_size / 1024**2:.1f} MB)"
    )


def _run_modal() -> int:
    RUNNER_PATH.write_text(RUNNER_SOURCE, encoding="utf-8")
    time.sleep(2)
    env = os.environ.copy()
    env["RABIT_VLLM_SNAPSHOT"] = str(SNAPSHOT_PATH)
    env.setdefault("PYTHONUTF8", "1")
    env.setdefault("PYTHONIOENCODING", "utf-8")
    command = [sys.executable, "-m", "modal", "run", str(RUNNER_PATH)]
    print("Running:", " ".join(command))
    with LOG_PATH.open("w", encoding="utf-8") as log:
        process = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            bufsize=1,
        )
        assert process.stdout is not None
        for line in process.stdout:
            print(line, end="")
            log.write(line)
            log.flush()
        return process.wait()


def main() -> None:
    print("RABIT-2 Stage 3A direct-Python installer and runner")
    print(f"Project root: {PROJECT_ROOT}")
    _install_files()
    _make_snapshot()
    code = _run_modal()
    if code != 0:
        raise SystemExit(code)
    print(f"Log saved to: {LOG_PATH}")


if __name__ == "__main__":
    main()
